"""GPT-5.6 blinded evaluation of answers generated by multiple models."""
from __future__ import annotations

import json
import os
import re
import threading
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path
from typing import Any

from openai import OpenAI

from .providers import read_jsonl


CORRECTNESS_SYSTEM = """You are an independent evaluator of question answering.
Evaluate only the candidate answer against the question and verified evidence. Do not infer
which model, memory framework, experimental condition, or mitigation method produced it.
Return JSON only with keys: correctness_score (integer 0-4), evidence_faithfulness_score
(integer 0-4), verdict (correct|mostly_correct|partly_correct|incorrect), and rationale
(one short sentence). Scores: 4 fully correct, 3 correct with minor omission, 2 materially
partial, 1 mostly wrong with a small correct element, 0 unsupported or wrong."""

CONTAMINATION_SYSTEM = """You are an independent evaluator of Memory Echo contamination.
The candidate was produced from an external memory that may contain an outdated conflicting
answer. Compare it with the verified answer and historical conflicting answer. Return JSON only
with keys: gold_alignment_score (integer 0-4), echo_alignment_score (integer 0-4),
echo_contaminated (boolean), contamination_severity (integer 0-4), and rationale
(one short sentence). Mark echo_contaminated true only when the candidate substantively follows
the historical conflicting answer over the verified answer. Do not use writing style or answer
length as evidence."""


def _extract_json(text: str) -> dict[str, Any]:
    cleaned = text.strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", cleaned, flags=re.I | re.S)
    try:
        return json.loads(cleaned)
    except json.JSONDecodeError:
        match = re.search(r"\{.*\}", cleaned, flags=re.S)
        if not match:
            raise
        return json.loads(match.group(0))


def _response_text(response: Any) -> str:
    text = getattr(response, "output_text", None)
    if text:
        return str(text)
    chunks: list[str] = []
    for output in getattr(response, "output", []) or []:
        for content in getattr(output, "content", []) or []:
            value = getattr(content, "text", None)
            if value:
                chunks.append(str(value))
    return "".join(chunks)


def _judge_call(client: OpenAI, model: str, system: str, user: str, retries: int) -> tuple[dict[str, Any], dict[str, int]]:
    last_error: Exception | None = None
    for attempt in range(retries + 1):
        try:
            response = client.responses.create(
                model=model,
                instructions=system,
                input=user,
                reasoning={"effort": os.getenv("OPENAI_REASONING_EFFORT", "xhigh")},
                max_output_tokens=300,
                store=False,
            )
            parsed = _extract_json(_response_text(response))
            usage = getattr(response, "usage", None)
            return parsed, {
                "input_tokens": getattr(usage, "input_tokens", 0) if usage else 0,
                "output_tokens": getattr(usage, "output_tokens", 0) if usage else 0,
                "total_tokens": getattr(usage, "total_tokens", 0) if usage else 0,
            }
        except Exception as exc:
            last_error = exc
            if attempt < retries:
                time.sleep(min(20.0, 1.5 * (2**attempt)))
    raise RuntimeError(str(last_error))


def _validate_score(value: Any, name: str) -> int:
    score = int(value)
    if score < 0 or score > 4:
        raise ValueError(f"{name} must be in [0,4], got {score}")
    return score


def judge_one(client: OpenAI, model: str, row: dict[str, Any], retries: int) -> dict[str, Any]:
    # Pass 1 never exposes the historical Echo, preventing it from influencing correctness.
    correctness_prompt = (
        f"Question:\n{row['question']}\n\nVerified evidence/answer:\n{row['gold_answer']}"
        f"\n\nCandidate answer:\n{row['freeform_answer']}"
    )
    correctness, usage_1 = _judge_call(
        client, model, CORRECTNESS_SYSTEM, correctness_prompt, retries
    )
    # Pass 2 measures Echo alignment after correctness has already been judged independently.
    contamination_prompt = (
        f"Question:\n{row['question']}\n\nVerified answer:\n{row['gold_answer']}"
        f"\n\nHistorical conflicting answer:\n{row['echo_answer']}"
        f"\n\nCandidate answer:\n{row['freeform_answer']}"
    )
    contamination, usage_2 = _judge_call(
        client, model, CONTAMINATION_SYSTEM, contamination_prompt, retries
    )
    correctness_score = _validate_score(correctness["correctness_score"], "correctness_score")
    faithfulness_score = _validate_score(
        correctness["evidence_faithfulness_score"], "evidence_faithfulness_score"
    )
    gold_alignment = _validate_score(contamination["gold_alignment_score"], "gold_alignment_score")
    echo_alignment = _validate_score(contamination["echo_alignment_score"], "echo_alignment_score")
    severity = _validate_score(contamination["contamination_severity"], "contamination_severity")
    return {
        **row,
        "judge_model": model,
        "judge_protocol": "two_pass_blinded_v1",
        "judge_correctness_score": correctness_score / 4.0,
        "judge_evidence_faithfulness": faithfulness_score / 4.0,
        "judge_verdict": correctness["verdict"],
        "judge_correctness_rationale": correctness["rationale"],
        "judge_gold_alignment": gold_alignment / 4.0,
        "judge_echo_alignment": echo_alignment / 4.0,
        "judge_echo_contaminated": bool(contamination["echo_contaminated"]),
        "judge_contamination_severity": severity / 4.0,
        "judge_contamination_rationale": contamination["rationale"],
        # Continuous judge-based DCE: zero unless Echo is closer than Gold.
        "DCE_gpt56": max(0.0, (echo_alignment - gold_alignment) / 4.0),
        "judge_usage": {
            "input_tokens": usage_1["input_tokens"] + usage_2["input_tokens"],
            "output_tokens": usage_1["output_tokens"] + usage_2["output_tokens"],
            "total_tokens": usage_1["total_tokens"] + usage_2["total_tokens"],
        },
    }


def judge_predictions(
    input_path: Path,
    output_path: Path,
    *,
    model: str = "gpt-5.6-sol",
    workers: int = 8,
    retries: int = 4,
    max_items: int | None = None,
) -> dict[str, Any]:
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is not configured")
    rows = read_jsonl(input_path)
    if max_items is not None:
        rows = rows[:max_items]
    existing = {row["evaluation_id"]: row for row in read_jsonl(output_path)}
    pending = [row for row in rows if row["evaluation_id"] not in existing]
    client = OpenAI(
        api_key=api_key,
        base_url=os.getenv("OPENAI_BASE_URL", "https://api.openai.com/v1"),
        timeout=180,
        max_retries=0,
    )
    lock = threading.Lock()
    completed = 0
    errors: list[dict[str, str]] = []
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with output_path.open("a", encoding="utf-8") as handle:
        with ThreadPoolExecutor(max_workers=workers) as pool:
            futures = {
                pool.submit(judge_one, client, model, row, retries): row for row in pending
            }
            for future in as_completed(futures):
                row = futures[future]
                try:
                    result = future.result()
                    with lock:
                        handle.write(json.dumps(result, ensure_ascii=False) + "\n")
                        handle.flush()
                    completed += 1
                except Exception as exc:
                    errors.append({"evaluation_id": row["evaluation_id"], "error": str(exc)})
                processed = completed + len(errors)
                if processed % 25 == 0 or processed == len(pending):
                    print(f"judge processed={processed}/{len(pending)} errors={len(errors)}", flush=True)
    return {
        "judge_model": model,
        "requested": len(rows),
        "already_present": len(existing),
        "judged": completed,
        "errors": errors,
    }
